using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
// Derived local pose packets, reference recipe only. No catalog promotion.
public static class FullRosterMotionContinuityGate {
 [Serializable]class Report {public string status,error,role;public int missingSupportVertices;public bool importedWeightsBitExact;public int originalVertices,seamVertices,coefficientBitDifferences,guardFrames,loopFrames,danceFrames,transitionFrames;public float guardDuration,loopDuration,danceDuration,sampleHz=96;public float maxCoefficientError,loopPositionError,loopQuaternionDotMin=1,transitionBoundaryPositionError,maxAdjacentRotationDeg;public string[] nodeNames;public int[] parents;public string scope="Full positive coefficient membership/readback, guard cyclic overlap24 keys, retarget dance zero twist,0.35s guard blend. Review packet, not runtime/phone acceptance.";}
 sealed class Pose {public Vector3[] p,s;public Quaternion[] q;public Pose(Transform[] nodes){p=nodes.Select(n=>n.localPosition).ToArray();s=nodes.Select(n=>n.localScale).ToArray();q=nodes.Select(n=>n.localRotation).ToArray();}public Pose(int n){p=new Vector3[n];s=new Vector3[n];q=new Quaternion[n];}}
 static Pose Blend(Pose a,Pose b,float t){var o=new Pose(a.p.Length);for(int i=0;i<o.p.Length;i++){o.p[i]=Vector3.Lerp(a.p[i],b.p[i],t);o.s[i]=Vector3.Lerp(a.s[i],b.s[i],t);o.q[i]=Quaternion.Slerp(a.q[i],b.q[i],t).normalized;}return o;}
 static void Write(string path,Pose[] poses){using(var w=new BinaryWriter(File.Create(path)))foreach(var f in poses)for(int i=0;i<f.p.Length;i++)foreach(float v in new[]{f.p[i].x,f.p[i].y,f.p[i].z,f.q[i].x,f.q[i].y,f.q[i].z,f.q[i].w,f.s[i].x,f.s[i].y,f.s[i].z})w.Write(v);}
 static float Smooth(float v){v=Mathf.Clamp01(v);return v*v*(3-2*v);}
 public static void Run(){string role=Environment.GetEnvironmentVariable("LF_DENSE_ROLE")??"master",root=Path.GetFullPath("../art/drafts/full-roster-v1/"),output=root+role+"-motion-continuity";Directory.CreateDirectory(output);var r=new Report{role=role,status="RUNNING"};GameObject actor=null;Native67AlternativeDanceReview alt=null;int exit=1;try{
 string path="Assets/Native67SpatialReview/"+char.ToUpperInvariant(role[0])+role.Substring(1)+"DenseReview.fbx";actor=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path));var skin=actor.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var mesh=skin.sharedMesh;var nodes=actor.GetComponentsInChildren<Transform>(true);r.nodeNames=nodes.Select(n=>n.name).ToArray();r.parents=nodes.Select(n=>Array.IndexOf(nodes,n.parent)).ToArray();
 string oracle=root+role+"-weight-oracle/";var expectedCounts=File.ReadAllBytes(oracle+"counts.bin");var jointBytes=File.ReadAllBytes(oracle+"joints.bin");var weightBytes=File.ReadAllBytes(oracle+"weights.bin");var expectedJoints=new ushort[jointBytes.Length/2];Buffer.BlockCopy(jointBytes,0,expectedJoints,0,jointBytes.Length);var expectedWeights=new float[weightBytes.Length/4];Buffer.BlockCopy(weightBytes,0,expectedWeights,0,weightBytes.Length);var boneNames=File.ReadAllLines(oracle+"bones.txt");var map=skin.bones.Select(b=>Array.IndexOf(boneNames,b.name)).ToArray();var offsets=new int[expectedCounts.Length+1];for(int i=0;i<expectedCounts.Length;i++)offsets[i+1]=offsets[i]+expectedCounts[i];var uv=mesh.uv2;var counts=mesh.GetBonesPerVertex();var weights=mesh.GetAllBoneWeights();var seen=new bool[expectedCounts.Length];int at=0;try{if(uv.Length!=mesh.vertexCount)throw new Exception("Missing source-ID UV");for(int i=0;i<mesh.vertexCount;i++){float raw=uv[i].x*2097152;int id=Mathf.RoundToInt(raw);if(id<0||id>=expectedCounts.Length||raw!=id)throw new Exception("Source-ID decode");seen[id]=true;if(counts[i]!=expectedCounts[id])r.missingSupportVertices++;for(int j=0;j<counts[i];j++){var w=weights[at++];int k=-1;for(int e=offsets[id];e<offsets[id+1];e++)if(expectedJoints[e]==map[w.boneIndex]){k=e;break;}if(k<0||w.weight<=0)throw new Exception("Positive named support mismatch");float error=Math.Abs(w.weight-expectedWeights[k]);r.maxCoefficientError=Math.Max(r.maxCoefficientError,error);if(w.weight!=expectedWeights[k])r.coefficientBitDifferences++;}}if(seen.Any(v=>!v))throw new Exception("Missing original vertex");r.originalVertices=seen.Length;r.seamVertices=mesh.vertexCount;}finally{counts.Dispose();weights.Dispose();}
 alt=new Native67AlternativeDanceReview(actor,skin);Environment.SetEnvironmentVariable("LF_NATIVE67_SOURCE_CLAVICLE","0");Environment.SetEnvironmentVariable("LF_NATIVE67_CLAVICLE_MOTION_GAIN","1");Environment.SetEnvironmentVariable("LF_NATIVE67_CLAVICLE_MATCH_TWIST","0");Environment.SetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_GAIN","1");Environment.SetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_FADE_SECONDS","0");var guard=alt.Prepare("action-guard");int frames=(int)Math.Ceiling(guard.length*96)+1;var g=new Pose[frames];for(int i=0;i<frames;i++){alt.Sample(guard.length*i/(frames-1));g[i]=new Pose(nodes);}r.guardDuration=guard.length;r.guardFrames=frames;const int overlap=24;var loop=g.Skip(overlap).ToArray();for(int i=0;i<=overlap;i++){int index=loop.Length-overlap-1+i;loop[index]=Blend(loop[index],g[i],Smooth((float)i/overlap));}r.loopFrames=loop.Length;for(int i=0;i<nodes.Length;i++){r.loopPositionError=Math.Max(r.loopPositionError,Vector3.Distance(loop[0].p[i],loop.Last().p[i]));r.loopQuaternionDotMin=Math.Min(r.loopQuaternionDotMin,Math.Abs(Quaternion.Dot(loop[0].q[i],loop.Last().q[i])));}if(r.loopPositionError>1e-7||r.loopQuaternionDotMin<.999999f)throw new Exception("Guard seam failure");Write(output+"/GuardLoop.bin",loop);
 var dance=alt.Prepare("action-67");Environment.SetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_GAIN","0");Environment.SetEnvironmentVariable("LF_NATIVE67_ARM_TWIST_FADE_SECONDS","0.25");frames=(int)Math.Ceiling(dance.length*96)+1;var d=new Pose[frames];var transition=new Pose[frames];float loopDuration=guard.length*(loop.Length-1)/(g.Length-1);r.loopDuration=loopDuration;r.danceDuration=dance.length;for(int f=0;f<frames;f++){float seconds=dance.length*f/(frames-1);alt.Sample(seconds);d[f]=new Pose(nodes);float position=(seconds%loopDuration)/loopDuration*(loop.Length-1);int index=Math.Min(loop.Length-2,(int)position);var gp=Blend(loop[index],loop[index+1],position-index);float w=Smooth(seconds/.35f)*Smooth((dance.length-seconds)/.35f);transition[f]=Blend(gp,d[f],w);if(f==0||f==frames-1)for(int j=0;j<nodes.Length;j++)r.transitionBoundaryPositionError=Math.Max(r.transitionBoundaryPositionError,Vector3.Distance(gp.p[j],transition[f].p[j]));if(f>0)for(int j=0;j<nodes.Length;j++)r.maxAdjacentRotationDeg=Math.Max(r.maxAdjacentRotationDeg,Quaternion.Angle(transition[f-1].q[j],transition[f].q[j]));}r.danceFrames=frames;r.transitionFrames=frames;Write(output+"/DanceZero.bin",d);Write(output+"/GuardDanceReturn.bin",transition);if(r.transitionBoundaryPositionError>1e-7)throw new Exception("Guard return boundary");r.importedWeightsBitExact=r.coefficientBitDifferences==0&&r.missingSupportVertices==0;r.status=r.importedWeightsBitExact?"POSE_LOOP_AND_WEIGHT_PASS_VISUAL_RUNTIME_PENDING":"POSE_LOOP_PASS_IMPORTED_WEIGHT_LOSS_REQUIRES_RAW_FLOAT32";exit=0;
 }catch(Exception e){r.status="FAILED_NOT_PROMOTED";r.error=e.ToString();Debug.LogException(e);}finally{alt?.Dispose();if(actor!=null)UnityEngine.Object.DestroyImmediate(actor);File.WriteAllText(output+"/report.json",JsonUtility.ToJson(r,true));EditorApplication.Exit(exit);}}
}
